//! 🧪️ Native root clone cursors reuse the actual projection owner and its original finite Source.
use semio_framework_value_control_contract::*;
use semio_framework_value_snapshot_projection::{ImmutableRootCloneCursor,ImmutableRootProjection,retained_clone::{RetainedClone,RetainedCloneCursor,RetainedCloneRef,RetainedCloneSource}};
use semio_framework_value_retirement::{OriginalRetirementFailure,retirement::RetireOwned,retirement::controlled::ControlledRetirement};
use semio_framework_value_clone_source_testing::FixtureSourceBirth;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[derive(Clone,Copy,Debug)]struct Root(u64);
impl RetireOwned for Root{type RetirementCursor=<u64 as RetireOwned>::RetirementCursor;fn retirement_seed(self)->Self::RetirementCursor{self.0.retirement_seed()}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self::RetirementCursor>())}fn controlled_retirement_supported()->bool{true}}
impl RetainedClone for Root{type Cursor=ImmutableRootCloneCursor<Self>;fn retained_clone_cursor()->Self::Cursor{Default::default()}}
unsafe impl ImmutableRootProjection for Root{
 fn root_projection_demand(_:RetainedCloneRef<'_,Self>)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:std::mem::size_of::<Self>()+std::mem::size_of::<Option<Self>>(),depth:1,..Default::default()})}
 fn root_projection_work_demand(_:RetainedCloneRef<'_,Self>)->Result<u64,ValueError>{Ok(1)}
 fn project_root_into<'r>(original:RetainedCloneRef<'_,Self>,output:&mut Option<Self>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let d=Self::root_projection_demand(original)?;if output.is_some(){return Err(ValueError::invariant("root output occupied"))}if !retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}assert!(effect.performed(1)?);*output=Some(*original.get());Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 fn recover_project_root_into<'r>(_:RetainedCloneRef<'_,Self>,_:&mut Option<Self>,_:&mut RetainedAllocationEffect<'_>,_:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{Err(ValueError::invariant("native root has no unrecorded callback"))}
}
trait Failure:std::fmt::Debug{fn progress(&self)->RetainedCloneProgress;}
impl Failure for ValueError{fn progress(&self)->RetainedCloneProgress{self.retained_progress()}}
impl Failure for OriginalRetirementFailure{fn progress(&self)->RetainedCloneProgress{self.retained_progress()}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn paid<'a,'b,P>(bank:&mut EffectBank,authority:&mut OriginalEffectAuthority<P>,context:&mut P::Context<'a,'b>,g:RetainedCloneGrant,units:u64)->Result<RetainedCloneStep,P::Failure>where 'b:'a,P:OriginalEffectProducer<Output=RetainedCloneStep>,P::Failure:Failure{
 let(mut action,mut answer)=(None,None);let mut heap=(0,0);for _ in 0..128{let((poll,actual),observed)=observe(||bank.run(g,units,|effect|{let before=effect.performed_boundary();let ready=authority.drive(context,effect,&mut action).unwrap();let work=effect.performed_since(before).unwrap();if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}));heap.0+=observed.0;heap.1+=observed.1;if let Some(actual)=actual{assert_eq!(actual,heap.0)}if matches!(poll,RetainedWorkPoll::Pending{..}){continue}assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.finish(&mut action).unwrap();let result=answer.take().unwrap();let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(Failure::progress);assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_ne!(bank.take_admitted(),Some(false));bank.post(p,g,heap);return result}panic!("root cursor original action exhausted its finite bound")
}
struct CloneDriver;
struct CloneContext<'a,'b>{cursor:&'a mut ImmutableRootCloneCursor<Root>,input:RetainedCloneRef<'b,Root>,source:OriginalSourceTurnIdentity,op:u8,maximum:u64}
impl OriginalEffectProducer for CloneDriver{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=CloneContext<'a,'b>where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.source)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{match c.op{0=>c.cursor.advance_into(c.input,4096,c.maximum,e,r),1=>c.cursor.begin_close_into(e,r),_=>c.cursor.close_into(4096,e,r)}}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{match c.op{0=>c.cursor.recover_advance_into(c.input,4096,c.maximum,e,r),1=>c.cursor.recover_begin_close_into(e,r),_=>c.cursor.recover_close_into(4096,e,r)}}
}
struct TakeDriver;
impl OriginalEffectProducer for TakeDriver{
 type Output=RetainedCloneStep;type Failure=ValueError;type Context<'a,'b>=(&'a mut ImmutableRootCloneCursor<Root>,&'a mut Option<Root>,OriginalSourceTurnIdentity)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.2)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>where 'b:'a{c.0.take(c.1,e,r)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>where 'b:'a{c.0.recover_take(c.1,e,r)}
}
struct RetireDriver<T:RetireOwned>(std::marker::PhantomData<T>);
impl<T:RetireOwned> OriginalEffectProducer for RetireDriver<T>{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a mut ControlledRetirement<T>,OriginalSourceTurnIdentity)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.1)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.0.step_into(4096,e,r)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.0.recover_step_into(4096,e,r)}
}
fn retire<T:RetireOwned>(value:T,bank:&mut EffectBank){let mut owner=ControlledRetirement::retain(value);let mut authority=OriginalEffectAuthority::new(RetireDriver::<T>(std::marker::PhantomData));for _ in 0..128{if owner.terminal_is_empty(){break}let g=grant(owner.next_demand(4096).unwrap());let units=owner.next_computational_work(4096).unwrap();let source=bank.source_witness().identity();paid(bank,&mut authority,&mut(&mut owner,source),g,units).unwrap();}assert!(owner.terminal_is_empty());assert!(authority.into_producer().is_ok());}
#[test]fn root_clone_uses_native_projection_and_paid_original_cursor_cancellation(){
 let law:serde_json::Value=serde_json::from_str(include_str!("law.json")).unwrap();for cut in law["cancellationCuts"].as_array().unwrap(){let bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut fixture=RetainedCloneSource::from_owner_in(Root(law["value"].as_u64().unwrap()),bank);fixture.with_bank(|input,bank|{let mut cursor=Root::retained_clone_cursor();let mut authority=OriginalEffectAuthority::new(CloneDriver);for _ in 0..cut.as_u64().unwrap(){if cursor.output_ready(){break}let d=cursor.advance_demands(input,4096,64).unwrap();let units=cursor.advance_work_demand(input,4096,64).unwrap();let source=bank.source_witness().identity();let mut context=CloneContext{cursor:&mut cursor,input,source,op:0,maximum:64};let before=*bank.wallet().original_work();let no=paid(bank,&mut authority,&mut context,RetainedCloneGrant{maximum_copy_bytes:0,..grant(d)},0).unwrap();assert_eq!(no.progress(),RetainedCloneProgress::default());assert_eq!(*bank.wallet().original_work(),before);paid(bank,&mut authority,&mut context,grant(d),units).unwrap();}assert!(authority.into_producer().is_ok());retire(cursor,bank);}).unwrap();for _ in 0..law["maximumTurns"].as_u64().unwrap(){if fixture.terminal_is_empty(){break}fixture.close_once().unwrap();}assert!(fixture.terminal_is_empty());}
 let bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut fixture=RetainedCloneSource::from_owner_in(Root(73),bank);fixture.with_bank(|input,bank|{let mut cursor=Root::retained_clone_cursor();let mut authority=OriginalEffectAuthority::new(CloneDriver);for _ in 0..128{if cursor.output_ready(){break}let g=grant(cursor.advance_demands(input,4096,64).unwrap());let units=cursor.advance_work_demand(input,4096,64).unwrap();let source=bank.source_witness().identity();paid(bank,&mut authority,&mut CloneContext{cursor:&mut cursor,input,source,op:0,maximum:64},g,units).unwrap();}assert!(cursor.output_ready());assert!(authority.into_producer().is_ok());let mut take=OriginalEffectAuthority::new(TakeDriver);let mut output=None;let g=grant(cursor.take_demand().unwrap());let units=cursor.take_work_demand().unwrap();let source=bank.source_witness().identity();paid(bank,&mut take,&mut(&mut cursor,&mut output,source),g,units).unwrap();assert_eq!(output.as_ref().unwrap().0,73);assert!(take.into_producer().is_ok());retire(output.take().unwrap(),bank);retire(cursor,bank);}).unwrap();for _ in 0..law["maximumTurns"].as_u64().unwrap(){if fixture.terminal_is_empty(){break}fixture.close_once().unwrap();}assert!(fixture.terminal_is_empty());
}
